  const personalData=useMemo(()=>{const map=new Map<string,any>();personal.forEach(x=>{const m=String(x.date).slice(0,7);const y=map.get(m)||{month:m,contributions:0,interest:0,repayments:0,expenses:0,profit:0};if(x.type==='contribution')y.contributions+=x.amount;if(x.type==='interest'||x.type==='penalty')y.interest+=x.amount;if(x.type==='loan_repayment')y.repayments+=x.amount;if(x.type==='expense_allocation'){y.expenses+=Math.abs(x.amount);y.profit-=Math.abs(x.amount)}map.set(m,y)});return [...map.values()]},[personal]);
